#include "ksGlobalFinalTask.h"
#include <iostream>
#include <stdexcept>
static void check(bool b){if(!b)throw std::runtime_error("Global final property failed");}
int main(){using T=ks::GlobalFinalTask;uint64_t cases=0;auto verify=[&](unsigned master,unsigned level,unsigned inverse,unsigned route,unsigned count,unsigned status,unsigned old,unsigned part){T t;unsigned resets=0,publications=0,children=0,guard=0;auto wanted=count?status:0;auto read=[&](T::Read r)->uint32_t{switch(r){case T::Read::Master:return master;case T::Read::Level:return level;case T::Read::Inverse:return inverse;case T::Read::Route:return route;case T::Read::PartCount:return count;case T::Read::Status:return status;case T::Read::OldStatus:return old;case T::Read::Part:return part;}return 0;};auto write=[&](T::Write w,uint16_t value){if(w==T::Write::Status){check(value==wanted&&wanted!=old);++publications;}else{check(value==0);++resets;}};auto store=[](){return 3;};while(t.stage()!=T::Stage::Complete){check(++guard<90);auto c=t.child();if(c!=T::Child::None){if(c==T::Child::Master)check(t.masterProduct()==uint32_t(uint16_t(master<<9))*0x8102);if(c==T::Child::Main)check(t.main()==(route?0:level<<8));if(c==T::Child::Muted)check(t.muted()==(route?level<<8:0));if(c==T::Child::Inverse){auto v=inverse^127;check(t.inverseWord()==((v<<8)|uint8_t(v<<1)));}if(c==T::Child::Status)check(t.status()==wanted);check(t.resumeChild());++children;continue;}auto cost=t.nextClocks(store),s=unsigned(t.stage());check(t.advanceBefore(cost-1,read,write,store)==0&&unsigned(t.stage())==s);check(t.advanceBefore(cost,read,write,store)==cost);}check(resets==2&&publications==unsigned(wanted!=old)&&children==4+unsigned(wanted!=old)&&t.handoff()==(part==0));++cases;};for(unsigned a=0;a<256;++a)for(unsigned b=0;b<256;++b){verify(a,b,a^b,b&1,1,64,255,2);verify(64,100,64,0,1,a,b,2);verify(255,255,255,a,b,a,255-a,2);}for(unsigned part=0;part<256;++part)verify(part,part,part,part,part,part,255-part,part);std::cout<<"PASS: "<<cases<<" pure final properties; all master/level, status/oldstatus, route/count bytepairs, allpartbytes; exact4/5DSP publications,2resets, inverse, status suppression, part0handoff and budget refusal\n";}
